exec tool declaration:
```ts
declare const tools: { mcp__codex_apps__instantly_ai_update_lead(args: {
  // User ID to assign the lead to
  assigned_to?: string;
  // Company name of the lead
  company_name?: string;
  // Custom variables to merge into the lead, e.g. {"past_customer":true}. Keys new to the campaign are registered on it automatically.
  custom_variables?: { [key: string]: string | number | boolean | null; };
  // First name of the lead
  first_name?: string;
  // Lead ID to update
  id: string;
  // Job title of the lead. Cannot be combined with a jobTitle/job_title key inside custom_variables.
  job_title?: string;
  // Last name of the lead
  last_name?: string;
  // Lead interest status value
  lt_interest_status?: number;
  // Personalization of the lead
  personalization?: string;
  // Phone number of the lead
  phone?: string;
  // Potential value of the lead
  pl_value_lead?: string;
  // Website of the lead
  website?: string;
}): Promise<CallToolResult<{ [key: string]: unknown; }>>; };
```

